from ute_ue.voice_call import DefaultBaseVoiceCall
from taf.ue.plugin.mtk.flow import StartVoiceCall, StopVoiceCall


class MtkVoiceCall(DefaultBaseVoiceCall):
    """Voice Call general object"""

    def __init__(self, name, ue_name, definition, at_executor, logger_name='mtk_ue'):
        """
        Construct new voice call

        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param at_executor: at command executor which will be used for sending at command to UE
        :param logger_name: where to put logs from this voice call
        """
        super(MtkVoiceCall, self).__init__(name, ue_name, definition, logger_name)
        self._at_executor = at_executor
        self._start_voice_call = StartVoiceCall(self._at_executor, self.get_call_to_number())
        self._stop_voice_call = StopVoiceCall(self._at_executor)

    def start_voice_call(self):
        """Starts voice call."""
        self._start_voice_call.execute()

    def stop_voice_call(self):
        """Stops voice call."""
        self._stop_voice_call.execute()

    def _start_call_on_ue(self, to):
        pass

    def _end_call_on_ue(self):
        pass

    def await_voice_call_finish(self):
        pass

    def is_finished(self):
        """Returns if Voice Call have finished."""
        pass

    def merge_into_conference(self, other_call):
        """Merge with other_call into conference."""
        pass

    def hold(self):
        """Holds ongoing voice call"""
        pass

    def retrieve(self):
        """Retrieves holded voice call"""
        pass

    def drop(self):
        """Drops incoming voice call"""
        pass

    def answer(self, with_video=False):
        """Answers incoming voice call"""
        pass

    def upgrade(self):
        """Upgrades to video call"""
        pass

    def downgrade(self):
        """Downgrades to voice call"""
        pass

    def send_dtmf(self, tones, tone_duration):
        """Sends DTMF tones through voice channel."""
        pass
